55. let desktopLogger: DesktopLogger | null = null;
56. 
57. function formatError(error: unknown): string {
58.   if (error instanceof Error) return error.stack ?? error.message;
59.   return String(error);
60. }
61. 
62. function reportDesktopError(context: string, error: unknown): void {
63.   const message = `${context}: ${formatError(error)}`;
64.   desktopLogger?.error(message);
65.   process.stderr.write(`[desktop] ${message}\n`);
66. }
67. 
68. function reportDesktopInfo(message: string): void {
69.   desktopLogger?.info(message);
70.   process.stdout.write(`[desktop] ${message}\n`);
71. }
72. 
73. function configureDesktopLogger(): void {
74.   try {
75.     desktopLogger = createDesktopLogger(
76.       join(app.getPath("userData"), "logs"),
77.     );
78.   } catch (error) {
79.     reportDesktopError("Failed to initialize persistent logging", error);
80.   }
81. }
82. 
83. function readDevelopmentUrl(): string | undefined {
84.   const candidate = process.env["ELECTRON_RENDERER_URL"];
85.   if (!candidate) return undefined;
86.   if (!isAllowedDevelopmentUrl(candidate)) {
87.     throw new Error(
88.       "ELECTRON_RENDERER_URL must be a loopback HTTP URL with an explicit port",
89.     );
90.   }
91.   return candidate;
92. }
93. 
94. function configureTestUserData(): void {
95.   const candidate = process.env["ELECTRON_USER_DATA_DIR"];
96.   if (!candidate) return;
97.   if (process.env["ELECTRON_TEST_MODE"] !== "1" || !isAbsolute(candidate)) {
98.     throw new Error(
99.       "ELECTRON_USER_DATA_DIR is available only in test mode and must be absolute",
100.     );
101.   }
102.   app.setPath("userData", resolve(candidate));
103. }
104. 
105. function getDesktopPlatform(): DesktopPlatform {
106.   if (process.platform === "darwin") return "macos";
107.   if (process.platform === "win32") return "windows";
108.   if (process.platform === "linux") return "linux";
109.   return "other";
110. }
111. 
112. function assertTrustedSender(
113.   event: IpcMainEvent | IpcMainInvokeEvent,
114. ): BrowserWindow {
115.   const window = BrowserWindow.fromWebContents(event.sender);
116.   if (!window || window !== mainWindow) {
117.     throw new Error("Rejected desktop IPC from an untrusted renderer");
118.   }
119.   return window;
120. }
