122. function registerIpcHandlers(): void {
123.   ipcMain.handle(
124.     DESKTOP_CHANNELS.getState,
125.     (event: IpcMainInvokeEvent, ...args: unknown[]): DesktopState => {
126.       if (!hasNoIpcArguments(args)) {
