128.       }
129.       const window = assertTrustedSender(event);
130.       return {
131.         appVersion: app.getVersion(),
132.         isFullscreen: isWindowFullscreen(window),
133.         logPath: desktopLogger?.filePath ?? "",
134.         platform: getDesktopPlatform(),
135.       };
136.     },
137.   );
